/*
 * A212797  Number of spanning trees in C_2 X C_n.
 * https://oeis.org/A212797
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = 14*a(n-1) – 63*a(n-2) + 100*a(n-3) – 63*a(n-4) +
 *            14*a(n-5) – a(n-6), n > 6 * Initial values: * a(1) = 2 * a(2) =
 *            32 * a(3) = 294 * a(4) = 2304 * a(5) = 16810 * a(6) = 117600 * *
 *            The sequence is generated by a linear recurrence, allowing quick
 *            computation of * any a(n). Results are memoised...
 * Range:     u8 n <= 2, u16 n <= 5, u32 n <= 11, u64 n <= 23, u128 n <= 48,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stddef.h>

/* Be careful with indices: idx_t is assumed unsigned. */
static seq_t *cache = NULL;      /* cache[1] holds a(1) ... */
static idx_t  cache_cap = 0;     /* allocated capacity (in terms, 0 means unallocated) */
static idx_t  current_max = 0;   /* highest computed index */

/* Helper to allocate or grow the cache array so that it can store up to n terms. */
static void ensure_cache(idx_t n)
{
    if (cache_cap < n)
    {
        size_t new_cap = (cache_cap == 0) ? 8 : (size_t)cache_cap * 2;
        if (new_cap < (size_t)n) new_cap = n;
        seq_t *tmp = (seq_t *)realloc(cache, (new_cap + 1) * sizeof(seq_t));
        if (!tmp) { /* Allocation failed – terminate */
            exit(EXIT_FAILURE);
        }
        cache = tmp;
        cache_cap = new_cap;
    }
}

/* Compute a(n) using the recurrence, filling the cache as necessary. */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;   /* undefined for index 0, return 0 */

    /* Ensure the cache can hold at least n entries. */
    ensure_cache(n);

    /* Compute any missing values up to n. */
    for (idx_t i = current_max + 1; i <= n; ++i)
    {
        if (i == 1)          cache[i] = (seq_t)2;
        else if (i == 2)     cache[i] = (seq_t)32;
        else if (i == 3)     cache[i] = (seq_t)294;
        else if (i == 4)     cache[i] = (seq_t)2304;
        else if (i == 5)     cache[i] = (seq_t)16810;
        else if (i == 6)     cache[i] = (seq_t)117600;
        else
        {
            /* Recurrence: a(i) = 14*a(i-1) – 63*a(i-2) + 100*a(i-3) – 63*a(i-4) + 14*a(i-5) – a(i-6) */
            seq_t v1 = cache[i-1];
            seq_t v2 = cache[i-2];
            seq_t v3 = cache[i-3];
            seq_t v4 = cache[i-4];
            seq_t v5 = cache[i-5];
            seq_t v6 = cache[i-6];

            seq_t val = (seq_t)14 * v1
                        - (seq_t)63 * v2
                        + (seq_t)100 * v3
                        - (seq_t)63 * v4
                        + (seq_t)14 * v5
                        - v6;
            cache[i] = val;
        }
    }

    current_max = (current_max >= n) ? current_max : n;
    return cache[n];
}
